mapper.sql:
WHERE (#{hq}=TRUE OR EXISTS(SELECT 1 FROM repair_member_stores ms WHERE ms.store_id=a.store_id AND ms.user_id=#{actor}))
   AND a.store_id=#{storeId}AND a.health_status=#{condition}
   AND a.lifecycle=#{lifecycle}
   AND (a.name LIKE #{keyword} ESCAPE '!' OR a.asset_code LIKE #{keyword} ESCAPE '!' OR a.model LIKE #{keyword} ESCAPE '!')
